const entries = [];
for (const [group, cat, born, rows] of groups) {
  for (const [id, name, tag, why, problemItSolves, rel] of rows) {
    entries.push({
      id,
      name,
      cat,
      born,
      tag,
      history: `${name} is a ${born.toLowerCase()} that ${tag.charAt(0).toLowerCase()}${tag.slice(1)}. Its guarantees and tradeoffs depend on the concrete implementation and operating context.`,
      why,
      problemItSolves,
      rel: { seeAlso: rel },
      challenges: [
        `Define ${name} and distinguish it from a neighboring concept.`,
        `Choose a realistic task where ${name} is appropriate.`,
        `Identify a failure mode caused by misusing ${name}.`,
        `Interpret a small design or result involving ${name}.`,
        `Explain one tradeoff or limitation of ${name}.`,
      ],
      extension: { problemItSolves, docs: [references[group]], updatedAt },
    });
  }
}

const batchIds = new Set();
const batchNames = new Set();
for (const entry of entries) {
  if (batchIds.has(entry.id) || batchNames.has(entry.name.toLowerCase()))
    throw new Error(`Repeated batch topic: ${entry.id} / ${entry.name}`);
  batchIds.add(entry.id);
  batchNames.add(entry.name.toLowerCase());
}

const existingNames = new Map(generated.map((item) => [item.name.toLowerCase(), item.id]));
let added = 0;
for (const entry of entries) {
  const byId = generated.findIndex(({ id }) => id === entry.id);
  const byName = existingNames.get(entry.name.toLowerCase());
  if (byId >= 0) generated[byId] = entry;
  else if (!byName) {
    generated.push(entry);
    existingNames.set(entry.name.toLowerCase(), entry.id);
    added += 1;
  }
}
generated.sort((a, b) => a.id.localeCompare(b.id));
fs.writeFileSync(output, `${JSON.stringify(generated, null, 2)}\n`);
console.log(`Published ${entries.length} foundational topics (${added} newly added).`);
